"use client";

import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";
import type { ReactNode } from "react";

import { cn } from "@/lib/utils";

const buttonVariants = cva(
  "group/button relative inline-flex shrink-0 items-center justify-center overflow-hidden whitespace-nowrap rounded-lg border border-transparent bg-clip-padding text-sm font-medium outline-none select-none transition-[background-color,border-color,box-shadow,color,opacity,transform] duration-200 ease-out hover:-translate-y-0.5 hover:shadow-sm active:translate-y-0 active:scale-[0.98] disabled:pointer-events-none disabled:opacity-50 data-[loading=true]:cursor-wait data-[loading=true]:opacity-90 focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default:
          "bg-primary text-primary-foreground shadow-xs hover:bg-primary/90",
        outline:
          "border-border bg-background shadow-xs hover:border-border/80 hover:bg-muted/70 hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50",
        secondary:
          "bg-secondary text-secondary-foreground shadow-xs hover:bg-secondary/80 aria-expanded:bg-secondary aria-expanded:text-secondary-foreground",
        ghost:
          "hover:bg-muted/70 hover:text-foreground hover:shadow-none dark:hover:bg-muted/50 aria-expanded:bg-muted aria-expanded:text-foreground",
        destructive:
          "border-destructive/20 bg-destructive/10 text-destructive shadow-xs hover:border-destructive/30 hover:bg-destructive/15 focus-visible:border-destructive/40 focus-visible:ring-destructive/20 dark:bg-destructive/20 dark:focus-visible:ring-destructive/40 dark:hover:bg-destructive/30",
        link: "text-primary underline-offset-4 hover:translate-y-0 hover:bg-transparent hover:shadow-none hover:underline active:scale-100",
      },
      size: {
        default:
          "h-8 gap-1.5 px-2.5 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2",
        xs: "h-6 gap-1 rounded-[min(var(--radius-md),10px)] px-2 text-xs in-data-[slot=button-group]:rounded-lg has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: "h-7 gap-1 rounded-[min(var(--radius-md),12px)] px-2.5 text-[0.8rem] in-data-[slot=button-group]:rounded-lg has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&_svg:not([class*='size-'])]:size-3.5",
        lg: "h-9 gap-1.5 px-2.5 has-data-[icon=inline-end]:pr-3 has-data-[icon=inline-start]:pl-3",
        icon: "size-8",
        "icon-xs":
          "size-6 rounded-[min(var(--radius-md),10px)] in-data-[slot=button-group]:rounded-lg [&_svg:not([class*='size-'])]:size-3",
        "icon-sm":
          "size-7 rounded-[min(var(--radius-md),12px)] in-data-[slot=button-group]:rounded-lg",
        "icon-lg": "size-9",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

type ButtonProps = ButtonPrimitive.Props &
  VariantProps<typeof buttonVariants> & {
    loading?: boolean;
    loadingText?: ReactNode;
    loadingIcon?: ReactNode;
  };

function Button({
  className,
  variant = "default",
  size = "default",
  loading = false,
  loadingText,
  loadingIcon,
  children,
  disabled,
  "aria-busy": ariaBusy,
  ...props
}: ButtonProps) {
  const isLoading = Boolean(loading);

  return (
    <ButtonPrimitive
      data-slot="button"
      data-loading={isLoading}
      aria-busy={ariaBusy ?? isLoading}
      disabled={disabled || isLoading}
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    >
      {isLoading ? (
        <>
          {loadingIcon ?? (
            <span
              data-slot="button-loading-icon"
              className="size-4 shrink-0 animate-spin rounded-full border-2 border-current/25 border-t-current"
              aria-hidden="true"
            />
          )}
          <span data-slot="button-loading-label">
            {loadingText ?? children}
          </span>
        </>
      ) : (
        children
      )}
    </ButtonPrimitive>
  );
}

export { Button, buttonVariants };

"use client";

import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
  type ComponentProps,
  type ReactNode,
  useEffect,
  useRef,
  useState,
} from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";

export const reactiveButtonVariants = tv({
  base: [
    "relative inline-flex shrink-0 items-center justify-center overflow-hidden whitespace-nowrap rounded-lg border border-transparent bg-clip-padding text-sm font-medium outline-none select-none",
    "transition-[background-color,border-color,box-shadow,color,opacity,transform] duration-200 ease-out",
    "hover:-translate-y-0.5 hover:shadow-sm active:translate-y-0 active:scale-[0.98] motion-reduce:transform-none",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
    "disabled:pointer-events-none disabled:opacity-50",
  ],
  variants: {
    variant: {
      default:
        "bg-primary text-primary-foreground shadow-xs hover:bg-primary/90",
      secondary:
        "bg-secondary text-secondary-foreground shadow-xs hover:bg-secondary/80",
      outline:
        "border-border bg-background shadow-xs hover:bg-muted/70 hover:text-foreground",
      ghost:
        "text-foreground hover:bg-muted/70 hover:text-foreground hover:shadow-none",
      destructive:
        "border-destructive/20 bg-destructive/10 text-destructive shadow-xs hover:border-destructive/30 hover:bg-destructive/15",
      link: "text-primary underline-offset-4 hover:translate-y-0 hover:bg-transparent hover:shadow-none hover:underline active:scale-100",
    },
    size: {
      sm: "h-7 gap-1 px-2.5 text-[0.8rem] [&_svg]:size-3.5",
      md: "h-8 gap-1.5 px-3 [&_svg]:size-4",
      lg: "h-9 gap-1.5 px-3.5 [&_svg]:size-4",
      icon: "size-8 [&_svg]:size-4",
    },
  },
  defaultVariants: {
    variant: "default",
    size: "md",
  },
});

export type ReactiveButtonStatus = "idle" | "loading" | "success" | "error";

export type ReactiveButtonProps = ComponentProps<"button"> &
  VariantProps<typeof reactiveButtonVariants> & {
    status?: ReactiveButtonStatus;
    loadingText?: ReactNode;
    successText?: ReactNode;
    errorText?: ReactNode;
    icon?: ReactNode;
    loadingIcon?: ReactNode;
    successIcon?: ReactNode;
    errorIcon?: ReactNode;
    autoReset?: boolean;
    resetDelay?: number;
    onStatusReset?: () => void;
  };

const statusStyles: Record<ReactiveButtonStatus, string> = {
  idle: "",
  loading: "cursor-wait",
  success: "border-chart-2/40 text-primary-foreground hover:border-chart-2/50",
  error:
    "border-destructive bg-destructive text-destructive-foreground hover:bg-destructive/90",
};

type AnimatedStatusIconProps = {
  shouldReduceMotion: boolean;
};

function LoadingIndicator({ shouldReduceMotion }: AnimatedStatusIconProps) {
  return (
    <svg
      data-slot="reactive-button-loading-icon"
      viewBox="0 0 24 24"
      fill="none"
      aria-hidden="true"
      focusable="false"
    >
      <circle
        cx="12"
        cy="12"
        r="8"
        stroke="currentColor"
        strokeWidth="1.75"
        opacity="0.24"
      />
      <motion.g
        style={{ transformOrigin: "12px 12px" }}
        animate={shouldReduceMotion ? undefined : { rotate: 360 }}
        transition={{
          duration: 0.9,
          ease: "linear",
          repeat: Number.POSITIVE_INFINITY,
        }}
      >
        <circle
          cx="12"
          cy="12"
          r="8"
          stroke="currentColor"
          strokeWidth="1.75"
          strokeLinecap="round"
          strokeDasharray="22 52"
        />
        <motion.circle
          cx="12"
          cy="4"
          r="1"
          fill="currentColor"
          animate={
            shouldReduceMotion ? undefined : { opacity: [0.45, 1, 0.45] }
          }
          transition={{
            duration: 0.9,
            ease: "easeInOut",
            repeat: Number.POSITIVE_INFINITY,
          }}
        />
      </motion.g>
    </svg>
  );
}

function AnimatedSuccessIcon({ shouldReduceMotion }: AnimatedStatusIconProps) {
  const drawTransition = shouldReduceMotion
    ? { duration: 0 }
    : { duration: 0.28, ease: [0.22, 1, 0.36, 1] as const };

  return (
    <svg
      data-slot="reactive-button-success-icon"
      viewBox="0 0 24 24"
      fill="none"
      aria-hidden="true"
      focusable="false"
    >
      <motion.circle
        cx="12"
        cy="12"
        r="8"
        stroke="currentColor"
        strokeWidth="1.5"
        style={{ transformOrigin: "12px 12px", rotate: -90 }}
        initial={shouldReduceMotion ? false : { opacity: 0, pathLength: 0 }}
        animate={{ opacity: 0.5, pathLength: 1 }}
        transition={drawTransition}
      />
      <motion.path
        d="m8.1 12.15 2.5 2.55 5.45-5.55"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        initial={shouldReduceMotion ? false : { opacity: 0, pathLength: 0 }}
        animate={{ opacity: 1, pathLength: 1 }}
        transition={
          shouldReduceMotion
            ? { duration: 0 }
            : {
                duration: 0.24,
                delay: 0.1,
                ease: [0.22, 1, 0.36, 1],
              }
        }
      />
    </svg>
  );
}

function AnimatedErrorIcon({ shouldReduceMotion }: AnimatedStatusIconProps) {
  return (
    <motion.svg
      data-slot="reactive-button-error-icon"
      viewBox="0 0 24 24"
      fill="none"
      aria-hidden="true"
      focusable="false"
      style={{ transformOrigin: "12px 12px" }}
      initial={shouldReduceMotion ? false : { rotate: -4, scale: 0.94 }}
      animate={{ rotate: 0, scale: 1 }}
      transition={
        shouldReduceMotion
          ? { duration: 0 }
          : { duration: 0.22, ease: [0.22, 1, 0.36, 1] }
      }
    >
      <motion.circle
        cx="12"
        cy="12"
        r="8"
        stroke="currentColor"
        strokeWidth="1.5"
        style={{ transformOrigin: "12px 12px", rotate: -90 }}
        initial={shouldReduceMotion ? false : { opacity: 0, pathLength: 0 }}
        animate={{ opacity: 0.62, pathLength: 1 }}
        transition={
          shouldReduceMotion
            ? { duration: 0 }
            : { duration: 0.26, ease: [0.22, 1, 0.36, 1] }
        }
      />
      <motion.path
        d="M12 7.75v5.4"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        initial={shouldReduceMotion ? false : { opacity: 0, pathLength: 0 }}
        animate={{ opacity: 1, pathLength: 1 }}
        transition={
          shouldReduceMotion
            ? { duration: 0 }
            : {
                duration: 0.18,
                delay: 0.1,
                ease: [0.22, 1, 0.36, 1],
              }
        }
      />
      <motion.circle
        cx="12"
        cy="16.3"
        r="1"
        fill="currentColor"
        style={{ transformOrigin: "12px 16.3px" }}
        initial={shouldReduceMotion ? false : { opacity: 0, scale: 0.35 }}
        animate={{ opacity: 1, scale: 1 }}
        transition={
          shouldReduceMotion
            ? { duration: 0 }
            : {
                type: "spring",
                delay: 0.2,
                stiffness: 360,
                damping: 22,
              }
        }
      />
    </motion.svg>
  );
}

function ReactiveButtonSurface({
  status,
  shouldReduceMotion,
}: {
  status: ReactiveButtonStatus;
  shouldReduceMotion: boolean;
}) {
  if (status === "idle") {
    return null;
  }

  return (
    <AnimatePresence initial={false} mode="wait">
      <motion.span
        key={status}
        data-slot="reactive-button-surface"
        className="pointer-events-none absolute inset-0"
        initial={shouldReduceMotion ? false : { opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={shouldReduceMotion ? undefined : { opacity: 0 }}
        transition={{ duration: shouldReduceMotion ? 0 : 0.18 }}
        aria-hidden="true"
      >
        {status === "loading" ? (
          <motion.span
            className="absolute inset-y-0 w-1/3 bg-foreground/10"
            initial={shouldReduceMotion ? { x: "0%" } : { x: "-120%" }}
            animate={
              shouldReduceMotion ? { x: "0%" } : { x: ["-120%", "360%"] }
            }
            transition={{
              duration: shouldReduceMotion ? 0 : 1.15,
              ease: "easeInOut",
              repeat: shouldReduceMotion ? 0 : Number.POSITIVE_INFINITY,
              repeatDelay: 0.12,
            }}
          />
        ) : null}

        {status === "success" ? (
          <>
            <motion.span
              className="absolute inset-0 bg-chart-2"
              style={{ transformOrigin: "left center" }}
              initial={shouldReduceMotion ? false : { scaleX: 0 }}
              animate={{ scaleX: 1 }}
              transition={{
                duration: shouldReduceMotion ? 0 : 0.34,
                ease: [0.22, 1, 0.36, 1],
              }}
            />
            <motion.span
              className="absolute inset-y-0 left-1/2 aspect-square -translate-x-1/2 rounded-full bg-background/20"
              initial={shouldReduceMotion ? false : { opacity: 0, scale: 0.7 }}
              animate={
                shouldReduceMotion
                  ? { opacity: 0 }
                  : { opacity: [0, 0.38, 0], scale: [0.7, 1.45] }
              }
              transition={{
                duration: shouldReduceMotion ? 0 : 0.46,
                delay: 0.08,
                ease: [0.22, 1, 0.36, 1],
              }}
            />
          </>
        ) : null}

        {status === "error" ? (
          <>
            <motion.span
              className="absolute inset-0 bg-destructive"
              style={{ transformOrigin: "center" }}
              initial={shouldReduceMotion ? false : { opacity: 0, scale: 0.96 }}
              animate={{ opacity: 1, scale: 1 }}
              transition={{
                duration: shouldReduceMotion ? 0 : 0.22,
                ease: [0.22, 1, 0.36, 1],
              }}
            />
            <motion.span
              className="absolute inset-0 bg-destructive-foreground/10"
              animate={
                shouldReduceMotion ? { opacity: 0 } : { opacity: [0, 0.4, 0] }
              }
              transition={{
                duration: shouldReduceMotion ? 0 : 0.34,
                ease: "easeOut",
              }}
            />
          </>
        ) : null}
      </motion.span>
    </AnimatePresence>
  );
}

function ReactiveButton({
  variant = "default",
  size = "md",
  status = "idle",
  loadingText = "Loading...",
  successText = "Done",
  errorText = "Try again",
  icon,
  loadingIcon,
  successIcon,
  errorIcon,
  autoReset = false,
  resetDelay = 1800,
  onStatusReset,
  className,
  children,
  disabled,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledby,
  "aria-busy": ariaBusy,
  ...props
}: ReactiveButtonProps) {
  const shouldReduceMotion = useReducedMotion();
  const [autoResetStatus, setAutoResetStatus] =
    useState<ReactiveButtonStatus | null>(null);
  const onStatusResetRef = useRef(onStatusReset);
  const visibleStatus = autoResetStatus === status ? "idle" : status;
  const isLoading = visibleStatus === "loading";
  const isIconButton = size === "icon";
  const resolvedAriaLabel =
    ariaLabel ??
    (isIconButton
      ? typeof children === "string"
        ? children
        : "Button action"
      : undefined);

  useEffect(() => {
    if (autoResetStatus && autoResetStatus !== status) {
      setAutoResetStatus(null);
    }
  }, [autoResetStatus, status]);

  useEffect(() => {
    onStatusResetRef.current = onStatusReset;
  }, [onStatusReset]);

  useEffect(() => {
    if (!autoReset || (status !== "success" && status !== "error")) {
      return;
    }

    const resetTimer = window.setTimeout(() => {
      setAutoResetStatus(status);
      onStatusResetRef.current?.();
    }, resetDelay);

    return () => window.clearTimeout(resetTimer);
  }, [autoReset, resetDelay, status]);

  const stateContent: Record<
    ReactiveButtonStatus,
    { icon?: ReactNode; label: ReactNode }
  > = {
    idle: { icon, label: children },
    loading: {
      icon: loadingIcon ?? (
        <LoadingIndicator shouldReduceMotion={Boolean(shouldReduceMotion)} />
      ),
      label: loadingText,
    },
    success: {
      icon: successIcon ?? (
        <AnimatedSuccessIcon shouldReduceMotion={Boolean(shouldReduceMotion)} />
      ),
      label: successText,
    },
    error: {
      icon: errorIcon ?? (
        <AnimatedErrorIcon shouldReduceMotion={Boolean(shouldReduceMotion)} />
      ),
      label: errorText,
    },
  };
  const activeContent = stateContent[visibleStatus];
  const transition = shouldReduceMotion
    ? { duration: 0 }
    : { duration: 0.18, ease: [0.22, 1, 0.36, 1] as const };

  return (
    <button
      type="button"
      data-slot="reactive-button"
      data-status={visibleStatus}
      aria-busy={ariaBusy ?? isLoading}
      aria-label={resolvedAriaLabel}
      aria-labelledby={ariaLabelledby}
      disabled={disabled || isLoading}
      className={twMerge(
        reactiveButtonVariants({ variant, size }),
        statusStyles[visibleStatus],
        className,
      )}
      {...props}
    >
      <ReactiveButtonSurface
        status={visibleStatus}
        shouldReduceMotion={Boolean(shouldReduceMotion)}
      />
      <span
        data-slot="reactive-button-content"
        className="relative z-10 grid items-center justify-items-center"
        aria-live={visibleStatus !== "idle" ? "polite" : undefined}
        aria-atomic="true"
      >
        {Object.entries(stateContent).map(([state, content]) => (
          <span
            key={`reactive-button-measure-${state}`}
            className="invisible col-start-1 row-start-1 inline-flex items-center gap-1.5"
            aria-hidden="true"
          >
            {content.icon ? <span className="size-4 shrink-0" /> : null}
            {!isIconButton ? content.label : null}
          </span>
        ))}

        <AnimatePresence initial={false} mode="popLayout">
          <motion.span
            key={visibleStatus}
            data-slot="reactive-button-state"
            className="col-start-1 row-start-1 inline-flex items-center gap-1.5"
            initial={shouldReduceMotion ? false : { opacity: 0, y: 2 }}
            animate={{ opacity: 1, y: 0 }}
            exit={shouldReduceMotion ? undefined : { opacity: 0, y: -2 }}
            transition={transition}
          >
            {activeContent.icon ? (
              <motion.span
                className="inline-flex shrink-0 items-center justify-center"
                initial={
                  shouldReduceMotion || visibleStatus !== "success"
                    ? false
                    : { scale: 0.82 }
                }
                animate={{ scale: 1 }}
                transition={transition}
                aria-hidden="true"
              >
                {activeContent.icon}
              </motion.span>
            ) : null}
            {isIconButton ? (
              <span className="sr-only">{activeContent.label}</span>
            ) : (
              activeContent.label
            )}
          </motion.span>
        </AnimatePresence>
      </span>
    </button>
  );
}

export { ReactiveButton };

import type { ComponentProps, MouseEvent, ReactNode } from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";

export const badgeVariants = tv({
  base: [
    "group/badge inline-flex min-w-0 shrink-0 items-center justify-center overflow-hidden border font-medium leading-none",
    "transition-[background-color,border-color,color,box-shadow,transform,opacity] duration-200 ease-out",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
    "motion-reduce:transition-none",
  ],

  variants: {
    variant: {
      default:
        "border-border/0 bg-primary text-primary-foreground hover:bg-primary/90",

      secondary:
        "border-border/0 bg-secondary text-secondary-foreground hover:bg-muted",

      destructive:
        "border-border bg-muted text-destructive shadow-[inset_0_1px_0_var(--color-border)] hover:bg-secondary",

      outline: "border-border bg-muted/0 text-foreground hover:bg-muted",

      ghost:
        "border-border/0 bg-muted/0 text-muted-foreground hover:border-border hover:bg-muted hover:text-foreground",

      soft: "border-border/0 bg-muted text-muted-foreground hover:text-foreground",

      dotted:
        "border-dashed border-border bg-muted/0 text-foreground hover:bg-muted",

      surface:
        "border-border bg-secondary text-secondary-foreground shadow-[0_1px_0_var(--color-border)] hover:bg-muted",

      inset:
        "border-border bg-muted text-foreground shadow-[inset_0_1px_0_var(--color-border),inset_0_-1px_0_var(--color-border)] hover:bg-secondary",

      tonal:
        "border-border/70 bg-primary/10 text-foreground shadow-[inset_0_1px_0_var(--color-border)] hover:bg-primary/10",

      muted:
        "border-border/70 bg-muted text-muted-foreground hover:text-foreground",

      success:
        "border-border bg-primary/10 text-foreground shadow-[inset_0_1px_0_var(--color-border)] hover:bg-primary/10",

      warning:
        "border-border bg-secondary text-foreground shadow-[inset_0_1px_0_var(--color-border)] hover:bg-muted",

      info: "border-border/70 bg-secondary text-secondary-foreground hover:bg-muted",

      pending:
        "border-dashed border-border bg-muted text-muted-foreground hover:text-foreground",

      pulse:
        "border-border bg-muted text-foreground shadow-[inset_0_1px_0_var(--color-border)] hover:bg-secondary",

      live: "border-border bg-primary/10 text-foreground hover:bg-primary/10",

      count:
        "min-w-5 rounded-full border-border bg-secondary px-1.5 text-secondary-foreground tabular-nums hover:bg-muted",

      keyboard:
        "border-border bg-muted px-1.5 font-mono text-muted-foreground shadow-[inset_0_-1px_0_var(--color-border)] hover:bg-secondary hover:text-foreground",

      beta: "border-border/70 bg-secondary text-muted-foreground uppercase tracking-wide hover:bg-muted hover:text-foreground",

      new: "border-border bg-primary/10 text-foreground uppercase tracking-wide hover:bg-primary/10",
    },
    size: {
      xs: "h-4 gap-1 px-1.5 text-[10px]",
      sm: "h-5 gap-1 px-2 text-[11px]",
      md: "h-6 gap-1.5 px-2.5 text-xs",
      lg: "h-7 gap-1.5 px-3 text-sm",
    },
    shape: {
      pill: "rounded-full",
      rounded: "rounded-md",
      square: "rounded-sm",
      dot: "rounded-full pl-1.5",
    },
    interactive: {
      true: [
        "cursor-pointer select-none hover:-translate-y-px active:translate-y-0 active:scale-[0.98]",
        "disabled:pointer-events-none disabled:opacity-50",
        "motion-reduce:hover:translate-y-0 motion-reduce:active:scale-100",
      ],
    },
    selected: {
      true: "border-border bg-muted text-foreground shadow-[inset_0_1px_0_var(--color-border)]",
    },
  },

  defaultVariants: {
    variant: "default",
    size: "sm",
    shape: "rounded",
  },

  compoundVariants: [
    {
      variant: "count",
      shape: "rounded",
      class: "rounded-full",
    },
  ],
});

type BadgeRootProps = Omit<ComponentProps<"span">, "children" | "color"> &
  Omit<ComponentProps<"button">, "children" | "className" | "color">;

export type BadgeProps = BadgeRootProps &
  VariantProps<typeof badgeVariants> & {
    children?: ReactNode;
    iconLeft?: ReactNode;
    iconRight?: ReactNode;
    dot?: boolean;
    pulse?: boolean;
    count?: ReactNode;
    dismissible?: boolean;
    dismissLabel?: string;
    onDismiss?: (event: MouseEvent<HTMLButtonElement>) => void;
  };

