            "[&_svg]:size-3.5",
            tone.indicator,
          )}
        >
          <ServiceIcon />
        </motion.span>
        <div className="min-w-0">
          <p className="truncate text-[13px] font-medium leading-4 text-foreground">
            {service.name}
          </p>
