          <Button
            type="button"
            variant="outline"
            size="sm"
            className="min-w-0 flex-1 sm:flex-none"
            onClick={actions.onCancel}
            disabled={isLoading}
          >
            {cancelLabel}
          </Button>

          <Button
            type="button"
            variant={tone === "destructive" ? "destructive" : "default"}
            size="sm"
            className="min-w-0 flex-1 sm:flex-none"
            onClick={actions.onConfirm}
            disabled={isLoading}
          >
            {isLoading ? confirmLabelLoading : confirmLabel}
          </Button>
        </div>
      </div>
    </>
  );
}

