};

export type CommandDockProps = Omit<ComponentProps<"div">, "onSelect"> &
  VariantProps<typeof commandDockVariants> & {
    actions: CommandDockAction[];
    activeId?: string;
    defaultActiveId?: string;
    onSelect?: (action: CommandDockAction) => void;
