export type FileUploadFileStatus = "idle" | "uploading" | "success" | "error";

export interface FileUploadFile {
  file: File;
  id: string;
  error?: string;
  status?: FileUploadFileStatus;
  progress?: number;
}

export type FileUploadProps = ComponentProps<"div"> &
  VariantProps<typeof fileUploadVariants> & {
    accept?: string;
    multiple?: boolean;
    maxSize?: number;
    maxFiles?: number;
    files?: FileUploadFile[];
    onFilesChange?: (files: FileUploadFile[]) => void;
    title?: string;
    description?: string;
    disabled?: boolean;
    uploading?: boolean;
  };

const smoothEase = [0.22, 1, 0.36, 1] as const;

const listVariants: Variants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: { staggerChildren: 0.035 },
  },
};

const itemVariants: Variants = {
  hidden: { opacity: 0, y: 6, scale: 0.98 },
  visible: {
    opacity: 1,
    y: 0,
    scale: 1,
    transition: { duration: 0.2, ease: smoothEase },
  },
  exit: {
    opacity: 0,
    x: 8,
    scale: 0.98,
    transition: { duration: 0.16, ease: smoothEase },
  },
};

function generateId() {
  return Math.random().toString(36).slice(2, 10);
}

function formatFileSize(bytes: number): string {
  if (bytes === 0) {
    return "0 B";
  }

  const units = ["B", "KB", "MB", "GB"];
  const index = Math.min(
    Math.floor(Math.log(bytes) / Math.log(1024)),
    units.length - 1,
  );

  return `${(bytes / 1024 ** index).toFixed(index === 0 ? 0 : 1)} ${
    units[index]
  }`;
}

function formatAccept(accept?: string) {
  if (!accept) {
    return "Any file";
  }

  return accept
    .split(",")
    .slice(0, 3)
    .map((item) => item.trim().replace("image/*", "images"))
    .join(", ");
}

function getEntryStatus(entry: FileUploadFile): FileUploadFileStatus {
  if (entry.error) {
    return "error";
  }

  return entry.status ?? "success";
}

function getStatusLabel(status: FileUploadFileStatus) {
  if (status === "uploading") {
    return "Uploading";
  }

  if (status === "success") {
    return "Ready";
  }

  if (status === "error") {
    return "Invalid";
  }

  return "Queued";
}

export function FileUpload({
  className,
  variant = "default",
  size = "md",
  state,
  accept,
  multiple = false,
  maxSize,
  maxFiles,
  files: controlledFiles,
  onFilesChange,
  title,
  description,
  disabled = false,
  uploading = false,
  ...props
}: FileUploadProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const inputId = useId();
  const shouldReduceMotion = useReducedMotion();
  const [dragging, setDragging] = useState(false);
  const [lastError, setLastError] = useState<string | null>(null);
  const [internalFiles, setInternalFiles] = useState<FileUploadFile[]>([]);

  const isControlled = controlledFiles !== undefined;
  const files = isControlled ? controlledFiles : internalFiles;
  const hasError = Boolean(lastError || files.some((entry) => entry.error));
  const resolvedState =
    state ?? (hasError ? "error" : uploading ? "uploading" : "default");

  const styles = fileUploadVariants({
    variant,
    size,
    isDragging: dragging,
    disabled,
    state: resolvedState,
  });

  const updateFiles = useCallback(
    (next: FileUploadFile[]) => {
      if (!isControlled) {
        setInternalFiles(next);
      }

      onFilesChange?.(next);
    },
    [isControlled, onFilesChange],
  );

  const validateFile = useCallback(
    (file: File): string | undefined => {
      if (maxSize && file.size > maxSize) {
        return `Larger than ${formatFileSize(maxSize)}`;
      }

      return undefined;
    },
    [maxSize],
  );

  const addFiles = useCallback(
    (incoming: File[]) => {
      if (disabled || incoming.length === 0) {
        return;
      }

      setLastError(null);

      const allowedSlots = multiple
        ? Math.max(
            (maxFiles ?? incoming.length + files.length) - files.length,
            0,
          )
        : 1;

      if (multiple && maxFiles && files.length + incoming.length > maxFiles) {
        setLastError(`Maximum ${maxFiles} files`);
      }

      if (allowedSlots === 0) {
        return;
      }

      const entries: FileUploadFile[] = incoming
        .slice(0, allowedSlots)
        .map((file) => {
          const error = validateFile(file);

          return {
            file,
            id: generateId(),
            error,
            status: error ? "error" : uploading ? "uploading" : "success",
            progress: uploading && !error ? 48 : undefined,
          };
        });

      updateFiles(multiple ? [...files, ...entries] : entries.slice(0, 1));
    },
    [disabled, files, maxFiles, multiple, updateFiles, uploading, validateFile],
  );

  const removeFile = useCallback(
    (id: string) => {
      updateFiles(files.filter((entry) => entry.id !== id));
    },
    [files, updateFiles],
  );

  const openFileDialog = useCallback(() => {
    if (!disabled) {
      inputRef.current?.click();
    }
  }, [disabled]);

  const handleDragOver = useCallback(
    (event: DragEvent<HTMLDivElement>) => {
      event.preventDefault();
      event.stopPropagation();

      if (!disabled) {
        setDragging(true);
      }
    },
    [disabled],
  );

  const handleDragLeave = useCallback((event: DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();

    if (!event.currentTarget.contains(event.relatedTarget as Node | null)) {
      setDragging(false);
    }
  }, []);

  const handleDrop = useCallback(
    (event: DragEvent<HTMLDivElement>) => {
      event.preventDefault();
      event.stopPropagation();
      setDragging(false);

      addFiles(Array.from(event.dataTransfer.files ?? []));
    },
    [addFiles],
  );

  const handleChange = useCallback(
    (event: ChangeEvent<HTMLInputElement>) => {
      addFiles(Array.from(event.target.files ?? []));
      event.target.value = "";
    },
    [addFiles],
  );

  const handleKeyDown = useCallback(
    (event: KeyboardEvent<HTMLDivElement>) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        openFileDialog();
      }
    },
    [openFileDialog],
  );

  const defaultTitle = dragging ? "Drop files here" : "Upload files";
  const defaultDescription = multiple
    ? "Drag files here or choose from your device"
    : "Drag a file here or choose from your device";

  return (
    <div
      data-slot="file-upload"
      className={twMerge(styles.root(), className)}
      {...props}
    >
      <motion.div
        data-slot="file-upload-dropzone"
        role="button"
        tabIndex={disabled ? -1 : 0}
        aria-label={title ?? defaultTitle}
        aria-disabled={disabled}
        data-disabled={disabled}
        onClick={openFileDialog}
        onKeyDown={handleKeyDown}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        className={styles.dropzone()}
        animate={
          shouldReduceMotion
            ? undefined
            : hasError
              ? { x: [0, -2, 2, -1, 1, 0] }
              : { scale: dragging ? 1.01 : 1 }
        }
        whileHover={
          shouldReduceMotion || disabled ? undefined : { y: -1, scale: 1.002 }
        }
        whileTap={shouldReduceMotion || disabled ? undefined : { scale: 0.998 }}
        transition={{ duration: hasError ? 0.24 : 0.2, ease: smoothEase }}
      >
        <motion.span
          className={styles.iconWrap()}
          animate={
            shouldReduceMotion
              ? undefined
              : { y: dragging ? -1 : 0, scale: dragging ? 1.04 : 1 }
          }
          transition={{ duration: 0.22, ease: smoothEase }}
          aria-hidden="true"
        >
          {resolvedState === "uploading" ? (
            <Loader2 className="size-4 animate-spin" />
          ) : resolvedState === "success" ? (
            <motion.span
              initial={shouldReduceMotion ? false : { scale: 0.7, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              transition={{ duration: 0.18, ease: smoothEase }}
            >
              <Check className="size-4" />
            </motion.span>
          ) : resolvedState === "error" ? (
            <AlertCircle className="size-4" />
          ) : (
            <Upload className="size-4" />
          )}
        </motion.span>

        <div className={styles.copy()}>
          <div className={styles.header()}>
            <span className={styles.title()}>{title ?? defaultTitle}</span>
            <span className={styles.badge()}>{formatAccept(accept)}</span>
          </div>
          <p className={styles.description()}>
            {description ?? defaultDescription}
          </p>
        </div>
      </motion.div>

      <input
        ref={inputRef}
        id={inputId}
        type="file"
        className="sr-only"
        accept={accept}
        multiple={multiple}
        disabled={disabled}
        onChange={handleChange}
      />

      <AnimatePresence initial={false}>
        {(files.length > 0 || lastError) && (
          <motion.div
            initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 4 }}
            animate={shouldReduceMotion ? { opacity: 1 } : { opacity: 1, y: 0 }}
            exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -4 }}
            transition={{ duration: 0.18, ease: smoothEase }}
          >
            {lastError ? (
              <p className={styles.error()} aria-live="polite">
                <AlertCircle className="size-3.5" aria-hidden="true" />
                {lastError}
              </p>
            ) : null}

            {files.length > 0 ? (
              <motion.ul
                data-slot="file-upload-list"
                className={styles.list()}
                variants={shouldReduceMotion ? undefined : listVariants}
                initial={shouldReduceMotion ? false : "hidden"}
                animate="visible"
              >
                <AnimatePresence initial={false}>
                  {files.map((entry) => {
                    const status = getEntryStatus(entry);
                    const progress =
                      entry.progress ?? (status === "uploading" ? 52 : 100);

                    return (
                      <motion.li
                        key={entry.id}
                        data-slot="file-upload-item"
                        layout
                        className={styles.item()}
                        variants={shouldReduceMotion ? undefined : itemVariants}
                        initial={shouldReduceMotion ? { opacity: 0 } : "hidden"}
                        animate={
                          shouldReduceMotion ? { opacity: 1 } : "visible"
                        }
                        exit={shouldReduceMotion ? { opacity: 0 } : "exit"}
                      >
                        <FileText
                          className={styles.fileIcon()}
                          aria-hidden="true"
                        />

                        <div className="min-w-0">
                          <p className={styles.fileName()}>{entry.file.name}</p>
                          <div className={styles.fileMeta()}>
                            <span>{formatFileSize(entry.file.size)}</span>
                            {entry.error ? <span>{entry.error}</span> : null}
                          </div>
                          {status === "uploading" ? (
                            <div
                              className={styles.progressTrack()}
                              aria-hidden="true"
                            >
                              <motion.div
                                className={styles.progressBar()}
                                initial={{ width: "12%" }}
                                animate={{ width: `${progress}%` }}
                                transition={{
                                  duration: 0.45,
                                  ease: smoothEase,
                                }}
                              />
                            </div>
                          ) : null}
                        </div>

                        <span className={styles.status()}>
                          {getStatusLabel(status)}
                        </span>

                        <button
                          type="button"
                          aria-label={`Remove ${entry.file.name}`}
                          className={styles.removeButton()}
                          disabled={disabled}
                          onClick={(event) => {
                            event.stopPropagation();
                            removeFile(entry.id);
                          }}
                        >
                          <X className="size-3.5" aria-hidden="true" />
                        </button>
                      </motion.li>
                    );
                  })}
                </AnimatePresence>
              </motion.ul>
            ) : null}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

