      stiffness: 420,
      damping: 34,
      mass: 0.78,
    },
  },
  exit: {
    opacity: 0,
    y: -18,
    scale: 0.985,
    transition: {
      duration: 0.16,
      ease: [0.32, 0, 0.67, 0],
    },
  },
};

const reducedCardVariants: Variants = {
  initial: { opacity: 1, y: 0, scale: 1 },
  animate: {
    opacity: 1,
    y: 0,
    scale: 1,
    transition: { duration: 0 },
  },
  exit: {
    opacity: 0,
    transition: { duration: 0.01 },
  },
};

const stackLayerVariants: Variants = {
  initial: { opacity: 0, scale: 0.96, y: 0 },
  animate: (i: number) => ({
    opacity: 1,
    scaleX: 1 - i * 0.026,
    scaleY: 1,
    y: i * 5,
    transition: {
      type: "spring",
      stiffness: 340,
      damping: 32,
      delay: i * 0.025,
    },
  }),
  exit: {
    opacity: 0,
    scale: 0.96,
    transition: { duration: 0.14 },
  },
};

const reducedStackLayerVariants: Variants = {
  initial: { opacity: 1, scale: 1, y: 0 },
  animate: (i: number) => ({
    opacity: 1,
    scaleX: 1 - i * 0.026,
    scaleY: 1,
    y: i * 5,
