  }),
  exit: {
    opacity: 0,
    transition: { duration: 0.01 },
  },
};

export type NotificationStackProps = ComponentProps<"div"> &
  VariantProps<typeof notificationStackVariants> & {
    notifications: NotificationData[];
    onDismiss?: (id: string) => void;
    maxStackLayers?: number;
  };

export function NotificationStack({
  className,
  size,
  notifications,
  onDismiss,
  maxStackLayers = 3,
  ...props
}: NotificationStackProps) {
  const shouldReduceMotion = useReducedMotion();
  const topNotification = notifications[notifications.length - 1];
  const stackCount = Math.min(notifications.length - 1, maxStackLayers);
  const remainingCount = notifications.length - 1;
  const activeCardVariants = shouldReduceMotion
    ? reducedCardVariants
    : cardVariants;
  const activeStackLayerVariants = shouldReduceMotion
    ? reducedStackLayerVariants
    : stackLayerVariants;

  function handleDragEnd(_: unknown, info: PanInfo) {
    if (!topNotification) {
      return;
    }

    if (Math.abs(info.offset.y) > 80 || Math.abs(info.offset.x) > 120) {
      onDismiss?.(topNotification.id);
    }
  }

  return (
    <div
      data-slot="notification-stack"
      className={twMerge(notificationStackVariants({ size }), className)}
      {...props}
    >
      <div
        className="relative w-full"
        style={{ paddingBottom: stackCount * 5 }}
      >
        <AnimatePresence>
          {Array.from({ length: stackCount }).map((_, i) => {
            const layerIndex = stackCount - i;

            return (
              <motion.div
                key={`stack-layer-${layerIndex}`}
                custom={layerIndex}
                variants={activeStackLayerVariants}
                initial="initial"
                animate="animate"
                exit="exit"
                className="absolute inset-x-0 bottom-0 top-0 z-0 origin-bottom"
                style={{ zIndex: i }}
              >
                <div
                  className={twMerge(
                    notificationCardVariants(),
                    "flex h-full w-full flex-col",
                  )}
                  style={{ opacity: 0.4 + i * 0.16 }}
                >
                  <div className="min-h-12 flex-1 rounded-xl border border-border bg-card/70" />
                </div>
              </motion.div>
            );
          })}
        </AnimatePresence>

        <AnimatePresence mode="popLayout">
          {topNotification ? (
            <motion.div
              key={topNotification.id}
              variants={activeCardVariants}
              initial="initial"
              animate="animate"
              exit="exit"
              drag
              dragConstraints={{ left: 0, right: 0, top: 0, bottom: 0 }}
              dragElastic={0.42}
              onDragEnd={handleDragEnd}
              className="relative cursor-grab active:cursor-grabbing"
              style={{ zIndex: stackCount + 1 }}
              whileHover={shouldReduceMotion ? undefined : { y: -1 }}
              whileTap={shouldReduceMotion ? undefined : { scale: 0.995 }}
              transition={{ type: "spring", stiffness: 420, damping: 34 }}
            >
              <div className={notificationCardVariants()}>
                <div className="flex min-h-6 items-center justify-between gap-2 pb-2">
                  <div className="flex min-w-0 items-center gap-1.5">
                    <span
                      className="size-1.25 shrink-0 rounded-full bg-secondary"
                      aria-hidden="true"
                    />
                    <div className="min-w-0">
                      {topNotification.app ? (
                        <motion.p
                          initial={shouldReduceMotion ? false : { opacity: 0 }}
                          animate={{ opacity: 1 }}
                          transition={{ duration: 0.18 }}
                          className="truncate text-[10px] font-medium uppercase leading-none text-muted-foreground"
                        >
                          {topNotification.app}
                        </motion.p>
                      ) : null}
                    </div>
                  </div>

                  <div className="flex shrink-0 items-center gap-2">
                    {topNotification.timestamp ? (
                      <motion.span
                        initial={shouldReduceMotion ? false : { opacity: 0 }}
                        animate={{ opacity: 1 }}
                        transition={{ delay: 0.08, duration: 0.18 }}
                        className="text-[10px] leading-none text-muted-foreground"
                      >
                        {topNotification.timestamp}
                      </motion.span>
                    ) : null}

                    <motion.button
                      type="button"
                      whileHover={
                        shouldReduceMotion ? undefined : { scale: 1.04 }
                      }
                      whileTap={
                        shouldReduceMotion ? undefined : { scale: 0.94 }
                      }
                      onClick={() => onDismiss?.(topNotification.id)}
                      aria-label="Dismiss notification"
                      className="flex size-6 items-center justify-center rounded-md border border-border bg-secondary text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2"
                    >
                      <X className="size-3" strokeWidth={2} />
                    </motion.button>
                  </div>
                </div>

                <div className="overflow-hidden rounded-xl border border-border bg-card text-foreground">
                  <div className="flex items-center gap-2 p-2">
                    {topNotification.avatar ? (
                      <motion.div
                        initial={
                          shouldReduceMotion
                            ? false
                            : { scale: 0.88, opacity: 0 }
                        }
                        animate={{ scale: 1, opacity: 1 }}
                        transition={{
                          type: "spring",
                          stiffness: 360,
                          damping: 24,
                          delay: 0.06,
                        }}
                        className="flex size-7 shrink-0 items-center justify-center overflow-hidden rounded-md border border-border bg-muted"
                      >
                        {topNotification.avatar}
                      </motion.div>
                    ) : null}

                    <div className="min-w-0 flex-1">
                      <p className="my-1.5 truncate text-sm font-medium leading-none text-foreground">
                        {topNotification.title}
                      </p>

                      {topNotification.description ? (
                        <p className="mb-0 mt-0.5 line-clamp-2 text-xs leading-[1.12] text-muted-foreground">
                          {topNotification.description}
                        </p>
                      ) : null}
                    </div>

                    {topNotification.action ? (
                      <motion.button
                        type="button"
                        initial={
                          shouldReduceMotion ? false : { opacity: 0, y: 4 }
                        }
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ delay: 0.14, duration: 0.2 }}
                        whileHover={shouldReduceMotion ? undefined : { y: -1 }}
                        whileTap={
                          shouldReduceMotion ? undefined : { scale: 0.96 }
                        }
                        onClick={topNotification.action.onClick}
                        className="shrink-0 rounded-md border border-border bg-secondary px-2 py-1 text-[11px] font-medium leading-none text-foreground transition-colors hover:bg-muted focus-visible:outline-2 focus-visible:outline-offset-2"
                      >
                        {topNotification.action.label}
                      </motion.button>
                    ) : null}
                  </div>
                </div>

                <motion.div
                  initial={shouldReduceMotion ? false : { opacity: 0, y: 3 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.18, duration: 0.2 }}
                  className="flex items-center justify-between gap-2 pt-2 text-[11px] leading-none text-muted-foreground"
                >
                  <span>
                    {remainingCount > 0
                      ? `${remainingCount} more notification${
                          remainingCount > 1 ? "s" : ""
                        }`
                      : "Swipe or close to dismiss"}
                  </span>
                  <span className="inline-flex items-center gap-1.5">
                    <span
                      className="size-1 rounded-full bg-secondary"
                      aria-hidden="true"
                    />
                    {notifications.length} active
                  </span>
                </motion.div>
              </div>
            </motion.div>
          ) : null}
        </AnimatePresence>
      </div>
    </div>
  );
}

"use client";

import { motion, useMotionValue, useSpring, useTransform } from "framer-motion";
import { ArrowDown, ArrowUp, Minus } from "lucide-react";
import { type ComponentProps, type ReactNode, useEffect } from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";

export const metricCardVariants = tv({
  base: [
    " not-prose w-full overflow-hidden rounded-[20px] border border-border",
    "bg-secondary text-foreground",
  ],
  variants: {
    size: {
      sm: "max-w-[280px]",
      md: "max-w-[340px]",
      lg: "max-w-[400px]",
    },
  },
  defaultVariants: {
    size: "md",
  },
});

const fadeUp = (delay = 0) =>
  ({
    initial: { opacity: 0, y: 8 },
    animate: { opacity: 1, y: 0 },
    transition: {
      duration: 0.4,
      ease: [0.25, 0.46, 0.45, 0.94] as const,
      delay,
    },
  }) as const;

export type MetricCardProps = ComponentProps<"div"> &
  VariantProps<typeof metricCardVariants> & {
    label: string;
    value: number;
    prefix?: string;
    suffix?: string;
    decimals?: number;
    trend?: {
      value: number;
      label?: string;
    };
    sparkline?: number[];
    footer?: ReactNode;
  };

export function MetricCard({
  className,
  size,
  label,
  value,
  prefix,
  suffix,
  decimals = 0,
  trend,
  sparkline,
  footer,
  ...props
}: MetricCardProps) {
  return (
    <div
      data-slot="metric-card"
      className={twMerge(metricCardVariants({ size }), className)}
      {...props}
    >
      <div className="px-4 py-1.5 ">
        <motion.span
          {...fadeUp(0)}
          className="text-[10px] font-medium uppercase tracking-widest text-muted-foreground"
        >
          {label}
        </motion.span>
      </div>

      <div className="mx-1.5 mb-1.5 overflow-hidden rounded-xl bg-card">
        <div className="space-y-3 p-4 pb-1">
          <div className="flex items-baseline justify-between gap-1.5">
            <AnimatedNumber
              value={value}
              prefix={prefix}
              suffix={suffix}
              decimals={decimals}
            />

            {trend && <TrendBadge value={trend.value} label={trend.label} />}
          </div>
        </div>

        {sparkline && sparkline.length > 1 && (
          <Sparkline data={sparkline} trend={trend?.value} />
        )}
      </div>
    </div>
  );
}

type AnimatedNumberProps = {
  value: number;
  prefix?: string;
  suffix?: string;
  decimals?: number;
};

function AnimatedNumber({
  value,
  prefix,
  suffix,
  decimals = 0,
}: AnimatedNumberProps) {
  const motionValue = useMotionValue(0);
  const spring = useSpring(motionValue, {
    stiffness: 80,
    damping: 20,
    mass: 1,
  });
  const display = useTransform(spring, (v) => {
    const formatted = v.toLocaleString("en-US", {
      minimumFractionDigits: decimals,
      maximumFractionDigits: decimals,
    });
    return `${prefix ?? ""}${formatted}${suffix ?? ""}`;
  });

  useEffect(() => {
    motionValue.set(value);
  }, [value, motionValue]);

  return (
    <motion.span
      {...fadeUp(0.08)}
      className="text-xl font-semibold leading-none tracking-[-0.03em]"
    >
      <motion.span>{display}</motion.span>
    </motion.span>
  );
}

type TrendBadgeProps = {
  value: number;
  label?: string;
};

function TrendBadge({ value, label }: TrendBadgeProps) {
  const isPositive = value > 0;
  const isNeutral = value === 0;

  const Icon = isNeutral ? Minus : isPositive ? ArrowUp : ArrowDown;

  return (
    <motion.div
      initial={{ opacity: 0, scale: 0.8, x: -4 }}
      animate={{ opacity: 1, scale: 1, x: 0 }}
      transition={{
        type: "spring",
        stiffness: 400,
        damping: 22,
        delay: 0.5,
      }}
      className={twMerge(
        "ml-1 flex items-center gap-0.5 rounded-full px-2 ",
        "text-[11px] font-medium",
        isPositive && "bg-chart-2/10 text-chart-2",
        !isPositive && !isNeutral && "bg-destructive/10 text-destructive",
        isNeutral && "bg-muted text-muted-foreground",
      )}
    >
      <Icon className="size-3" strokeWidth={2.5} />
      <span>
        {isPositive ? "+" : ""}
        {value}%
      </span>
      {label && (
        <span className="ml-0.5 text-[10px] text-muted-foreground/80">
          {label}
        </span>
      )}
    </motion.div>
  );
}

type SparklineProps = {
  data: number[];
  trend?: number;
};

function Sparkline({ data, trend = 0 }: SparklineProps) {
  const width = 320;
  const height = 64;
  const padding = 0;

  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = max - min || 1;

  const points = data.map((v, i) => {
    const x = padding + (i / (data.length - 1)) * (width - padding * 2);
    const y = height - padding - ((v - min) / range) * (height - padding * 2);
    return { x, y };
  });

  const pathD = points
    .map((p, i) => {
      if (i === 0) return `M ${p.x} ${p.y}`;
      const prev = points[i - 1];
      const cpx1 = prev.x + (p.x - prev.x) * 0.4;
      const cpx2 = prev.x + (p.x - prev.x) * 0.6;
      return `C ${cpx1} ${prev.y} ${cpx2} ${p.y} ${p.x} ${p.y}`;
    })
    .join(" ");

  const areaD = `${pathD} L ${points[points.length - 1].x} ${height} L ${points[0].x} ${height} Z`;

  const strokeColor =
    trend > 0
      ? "var(--chart-2)"
      : trend < 0
        ? "var(--destructive)"
        : "var(--muted-foreground)";

  const gradientId = `sparkline-gradient-${Math.random().toString(36).slice(2, 8)}`;

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ delay: 0.35, duration: 0.5 }}
    >
      <svg
        viewBox={`0 0 ${width} ${height}`}
        className="w-full"
        preserveAspectRatio="none"
      >
        <title>Trend sparkline chart</title>
        <defs>
          <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={strokeColor} stopOpacity={0.12} />
            <stop offset="100%" stopColor={strokeColor} stopOpacity={0} />
          </linearGradient>
        </defs>

        <motion.path
          d={areaD}
          fill={`url(#${gradientId})`}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.6, duration: 0.4 }}
        />

        <motion.path
          d={pathD}
          fill="none"
          stroke={strokeColor}
          strokeWidth={2}
          strokeLinecap="round"
          strokeLinejoin="round"
          initial={{ pathLength: 0 }}
          animate={{ pathLength: 1 }}
          transition={{
            duration: 1.2,
            ease: [0.16, 1, 0.3, 1],
            delay: 0.3,
          }}
        />

        <motion.circle
          cx={points[points.length - 1].x}
          cy={points[points.length - 1].y}
          r={3}
          fill={strokeColor}
          initial={{ scale: 0, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          transition={{ delay: 1.4, type: "spring", stiffness: 400 }}
        />
      </svg>
    </motion.div>
  );
}

export { AnimatedNumber, TrendBadge, Sparkline };

"use client";

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type Variants,
} from "framer-motion";
import {
  type ComponentProps,
  type KeyboardEvent,
  type ReactNode,
  useId,
  useRef,
  useState,
} from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";

export const motionTabsVariants = tv({
  base: [
    "w-full overflow-hidden rounded-[1.25rem] border border-border",
    "bg-secondary p-2 text-foreground",
  ],
  variants: {
    size: {
      sm: "max-w-[420px]",
      md: "max-w-[620px]",
      lg: "max-w-[760px]",
    },
  },
  defaultVariants: {
    size: "md",
  },
});

const panelVariants: Variants = {
  hidden: { opacity: 0, y: 8, scale: 0.985 },
  visible: {
    opacity: 1,
    y: 0,
    scale: 1,
    transition: { duration: 0.32, ease: [0.16, 1, 0.3, 1] },
  },
  exit: {
    opacity: 0,
    y: -4,
    scale: 0.99,
    transition: { duration: 0.16, ease: [0.3, 0, 1, 1] },
  },
};

export type MotionTabItem = {
  value: string;
  label: ReactNode;
  icon?: ReactNode;
  badge?: ReactNode;
  description?: ReactNode;
  content?: ReactNode;
  disabled?: boolean;
};

export type MotionTabsProps = Omit<ComponentProps<"div">, "defaultValue"> &
  VariantProps<typeof motionTabsVariants> & {
    items: MotionTabItem[];
    value?: string;
    defaultValue?: string;
    onValueChange?: (value: string) => void;
    listClassName?: string;
    panelClassName?: string;
  };

function toDomId(value: string) {
  return value.toLowerCase().replace(/[^a-z0-9_-]+/g, "-");
}

function MotionTabs({
  className,
  size,
  items,
  value,
  defaultValue,
  onValueChange,
  listClassName,
  panelClassName,
  ...props
}: MotionTabsProps) {
  const shouldReduceMotion = useReducedMotion();
  const generatedId = useId().replace(/:/g, "");
  const buttonRefs = useRef<Array<HTMLButtonElement | null>>([]);
  const firstEnabled = items.find((item) => !item.disabled)?.value;
  const [internalValue, setInternalValue] = useState(
    defaultValue ?? firstEnabled ?? items[0]?.value,
  );

  const selectedValue = value ?? internalValue;
  const selectedItem =
    items.find((item) => item.value === selectedValue && !item.disabled) ??
    items.find((item) => !item.disabled) ??
    items[0];

  function setSelected(nextValue: string) {
    if (value === undefined) {
      setInternalValue(nextValue);
    }
    onValueChange?.(nextValue);
  }

  function moveFocus(currentIndex: number, direction: 1 | -1) {
    if (!items.length) {
      return;
    }

    let nextIndex = currentIndex;

    for (let step = 0; step < items.length; step += 1) {
      nextIndex = (nextIndex + direction + items.length) % items.length;
      const nextItem = items[nextIndex];

      if (!nextItem?.disabled) {
        setSelected(nextItem.value);
        buttonRefs.current[nextIndex]?.focus();
        return;
      }
    }
  }

  function handleKeyDown(
    event: KeyboardEvent<HTMLButtonElement>,
    index: number,
  ) {
    if (event.key === "ArrowRight" || event.key === "ArrowDown") {
      event.preventDefault();
      moveFocus(index, 1);
      return;
    }

    if (event.key === "ArrowLeft" || event.key === "ArrowUp") {
      event.preventDefault();
      moveFocus(index, -1);
      return;
    }

    if (event.key === "Home") {
      event.preventDefault();
      const nextIndex = items.findIndex((item) => !item.disabled);
      const nextItem = items[nextIndex];

      if (nextItem) {
        setSelected(nextItem.value);
        buttonRefs.current[nextIndex]?.focus();
      }
      return;
    }

    if (event.key === "End") {
      event.preventDefault();

      let nextIndex = -1;
      for (let index = items.length - 1; index >= 0; index -= 1) {
        if (!items[index]?.disabled) {
          nextIndex = index;
          break;
        }
      }

      const nextItem = items[nextIndex];

      if (nextItem) {
        setSelected(nextItem.value);
        buttonRefs.current[nextIndex]?.focus();
      }
    }
  }

  if (!items.length) {
    return null;
  }

  return (
    <div
      data-slot="motion-tabs"
      className={twMerge(motionTabsVariants({ size }), className)}
      {...props}
    >
      <div
        data-slot="motion-tabs-list"
        role="tablist"
        aria-orientation="horizontal"
        className={twMerge(
          "relative flex gap-1 overflow-x-auto rounded-xl border border-border bg-background p-1",
          "supports-[scrollbar-width:none]:[scrollbar-width:none] [&::-webkit-scrollbar]:hidden",
          listClassName,
        )}
      >
        {items.map((item, index) => {
          const isSelected = item.value === selectedItem?.value;
          const itemDomId = `${generatedId}-${toDomId(item.value)}`;

          return (
            <motion.button
              key={item.value}
              ref={(node) => {
                buttonRefs.current[index] = node;
              }}
              type="button"
              role="tab"
              id={`${itemDomId}-trigger`}
              aria-controls={`${itemDomId}-panel`}
              aria-selected={isSelected}
              tabIndex={isSelected ? 0 : -1}
              disabled={item.disabled}
              data-slot="motion-tabs-trigger"
              data-active={isSelected ? "" : undefined}
              onClick={() => setSelected(item.value)}
              onKeyDown={(event) => handleKeyDown(event, index)}
              whileHover={
                item.disabled || shouldReduceMotion ? undefined : { y: -1 }
              }
              whileTap={
                item.disabled || shouldReduceMotion
                  ? undefined
                  : { scale: 0.98 }
              }
              className={twMerge(
                "group relative flex h-10 min-w-[7.5rem] flex-1 items-center justify-center gap-2 rounded-lg px-3",
                "text-sm font-medium outline-none transition-colors duration-200",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
                "disabled:pointer-events-none disabled:opacity-45",
                isSelected
                  ? "text-foreground"
                  : "text-muted-foreground hover:text-foreground",
              )}
            >
              {isSelected ? (
                <motion.span
                  layoutId={`${generatedId}-motion-tabs-indicator`}
                  data-slot="motion-tabs-indicator"
                  className="absolute inset-0 rounded-lg border border-border bg-card"
                  transition={{
                    type: "spring",
                    stiffness: 420,
                    damping: 34,
                    mass: 0.8,
                  }}
                />
              ) : null}

              {item.icon ? (
                <motion.span
                  aria-hidden="true"
                  data-slot="motion-tabs-icon"
                  animate={
                    shouldReduceMotion
                      ? undefined
                      : {
                          scale: isSelected ? 1.05 : 1,
                          rotate: isSelected ? 0 : -2,
                        }
                  }
                  transition={{ duration: 0.2, ease: "easeOut" }}
                  className={twMerge(
                    "relative z-10 flex items-center text-muted-foreground transition-colors duration-200",
                    "group-data-[active]:text-primary [&_svg]:size-4",
                  )}
                >
                  {item.icon}
                </motion.span>
              ) : null}

              <span className="relative z-10 truncate">{item.label}</span>

              {item.badge ? (
                <motion.span
                  data-slot="motion-tabs-badge"
                  animate={
                    shouldReduceMotion
                      ? undefined
                      : {
                          scale: isSelected ? 1 : 0.94,
                          opacity: isSelected ? 1 : 0.72,
                        }
                  }
                  transition={{ duration: 0.18, ease: "easeOut" }}
                  className="relative z-10 rounded-full border border-border bg-muted px-1.5 py-0.5 text-[10px] text-muted-foreground"
                >
                  {item.badge}
                </motion.span>
              ) : null}
            </motion.button>
          );
        })}
      </div>

      {selectedItem?.content ? (
        <AnimatePresence mode="wait" initial={false}>
          <motion.div
            key={selectedItem.value}
            data-slot="motion-tabs-panel"
            role="tabpanel"
            id={`${generatedId}-${toDomId(selectedItem.value)}-panel`}
            aria-labelledby={`${generatedId}-${toDomId(
              selectedItem.value,
            )}-trigger`}
            variants={panelVariants}
            initial={shouldReduceMotion ? false : "hidden"}
            animate="visible"
            exit={shouldReduceMotion ? undefined : "exit"}
            className={twMerge(
              "mt-2 rounded-xl border border-border bg-background p-4",
              panelClassName,
            )}
          >
            {selectedItem.description ? (
              <p
                data-slot="motion-tabs-description"
                className="mb-3 text-muted-foreground text-sm leading-relaxed"
              >
                {selectedItem.description}
              </p>
            ) : null}
            {selectedItem.content}
          </motion.div>
        </AnimatePresence>
      ) : null}
    </div>
  );
}

