      },
      default: {},
      roomy: {
        inner: "p-5 sm:p-6",
        header: "px-5 pt-5 pb-3 sm:px-6",
        footer: "px-5 pt-3 pb-5 sm:px-6",
      },
    },
  },
  defaultVariants: {
    size: "default",
  },
});

export type FormSectionProps = Omit<
  ComponentProps<"section">,
  keyof MotionProps
> &
  VariantProps<typeof formSectionVariants> & {
    title?: ReactNode;
    description?: ReactNode;
    actions?: ReactNode;
    footer?: ReactNode;
    children?: ReactNode;
  };

export function FormSection({
  className,
  style,
  size = "default",
  title,
  description,
  actions,
  footer,
  children,
  ...props
}: FormSectionProps) {
  const shouldReduceMotion = useReducedMotion();
  const styles = formSectionVariants({ size });
  const hasHeader = Boolean(title || description || actions);

  return (
    <motion.section
      data-slot="form-section"
      className={twMerge(styles.root(), className)}
      initial={shouldReduceMotion ? false : { opacity: 0, y: 4 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.34, ease: [0.4, 0, 0.2, 1] }}
      style={{
        backgroundImage: outerCardBackground,
        backgroundRepeat: "repeat",
        backgroundSize: "48px 48px",
        backgroundClip: "padding-box",
        ...style,
      }}
      {...props}
    >
      {hasHeader ? (
        <header data-slot="form-section-header" className={styles.header()}>
          <div>
            {title ? (
              <h3 data-slot="form-section-title" className={styles.title()}>
                {title}
              </h3>
            ) : null}
            {description ? (
              <p
                data-slot="form-section-description"
                className={styles.description()}
              >
                {description}
              </p>
            ) : null}
          </div>
          {actions}
        </header>
      ) : null}
      <div
        data-slot="form-section-inner"
        className={twMerge(
          styles.inner(),
          !hasHeader && "mt-2",
          !footer && "mb-2",
        )}
      >
        {children}
      </div>
      {footer ? (
        <footer data-slot="form-section-footer" className={styles.footer()}>
          {footer}
        </footer>
      ) : null}
    </motion.section>
  );
}

